export function getSketchfabUid(productName: string): string | null {
  const parts = productName.split(" ");
  if (parts.length < 2) return null;
  const style = parts.slice(1).join(" ");
  return sketchfabMap[style] ?? null;
}

export function getSketchfabEmbedUrl(uid: string): string {
  const params = [
    "ui_animations=0", "ui_infos=0", "ui_stop=0", "ui_inspector=0",
    "ui_watermark_link=0", "ui_watermark=0", "ui_ar=0", "ui_help=0",
    "ui_settings=0", "ui_vr=0", "ui_fullscreen=0", "ui_annotations=0",
    "autostart=1",
  ].join("&");
  return `https://sketchfab.com/models/${uid}/embed?${params}`;
}
